// Scene "main": graph of "guard" (object 1)
class FlowGraphScript_0_1 : public Script {
 public:
  void update(ScriptContext& ctx) override {
    if (ctx.scene != 0) return;
    if (ctx.sceneGeneration != generation) {
      // scene was (re)loaded - back to the initial state
      generation = ctx.sceneGeneration;
      frame = 0;
      started = false;
      seen3 = false;
    }
    frame++;
    if (!started) {
      started = true;
      {
        static const int navWps2[] = {3, 4, 5};  // wp1 wp2 wp3
        navPatrol(ctx, 1, navWps2, 3, 2.5F, 0.6F, 0);
      }
    }
    {
      const bool isSeen = navPlayerSeen(ctx, 1, 12.0F, 100.0F, 1);
      if (isSeen && !seen3) {
      navChase(ctx, 1, 3.0F, 1.5F, 25.0F);
      }
      seen3 = isSeen;
    }
  }

 private:
  unsigned int generation = 0;
  int frame = 0;
  bool started = false;
  bool seen3 = false;
};

// Scene "main": graph of "rabbit" (object 2)
class FlowGraphScript_0_2 : public Script {
 public:
  void update(ScriptContext& ctx) override {
    if (ctx.scene != 0) return;
    if (ctx.sceneGeneration != generation) {
      // scene was (re)loaded - back to the initial state
      generation = ctx.sceneGeneration;
      frame = 0;
      started = false;
      seen1 = false;
    }
    frame++;
    {
      const bool isSeen = navPlayerSeen(ctx, 2, 10.0F, 180.0F, 0);
      if (isSeen && !seen1) {
      navFlee(ctx, 2, 4.0F, 22.0F);
      }
      seen1 = isSeen;
    }
  }

 private:
  unsigned int generation = 0;
  int frame = 0;
  bool started = false;
  bool seen1 = false;
};

